/**
 * Plays Hindi lesson audio through the device (and any paired Bluetooth speaker).
 *
 * Order of preference:
 *   1. a clip saved on this device with an offline lesson pack;
 *   2. a clip generated by the server (Sarvam Bulbul) — needs internet;
 *   3. the device's own Hindi voice (speechSynthesis), if one is installed.
 * If none is available the text stays on screen and the UI says so.
 * Nothing autoplays: playback starts from a teacher/leader tap.
 */
import { api } from "@/lib/api";
import { getAudio } from "@/features/offline/db";

export type VoiceSource = "saved_clip" | "server_clip" | "device_voice" | "none";

export interface PlayHandle {
  source: VoiceSource;
  done: Promise<void>;
  stop: () => void;
  element?: HTMLAudioElement;
}

const memoryCache = new Map<string, Blob>();
let current: PlayHandle | null = null;

export function hindiDeviceVoice(): SpeechSynthesisVoice | null {
  if (typeof window === "undefined" || !("speechSynthesis" in window)) return null;
  const voices = window.speechSynthesis.getVoices();
  return voices.find((v) => v.lang?.toLowerCase().startsWith("hi")) ?? null;
}

export function stopSpeaking() {
  current?.stop();
  current = null;
}

function playBlob(blob: Blob, source: VoiceSource): PlayHandle {
  const url = URL.createObjectURL(blob);
  const el = new Audio(url);
  let stopFn = () => {};
  const done = new Promise<void>((resolve) => {
    const finish = () => {
      URL.revokeObjectURL(url);
      resolve();
    };
    el.onended = finish;
    el.onerror = finish;
    stopFn = () => {
      el.pause();
      finish();
    };
  });
  void el.play().catch(() => stopFn());
  return { source, done, stop: () => stopFn(), element: el };
}

function speakWithDevice(text: string): PlayHandle | null {
  const voice = hindiDeviceVoice();
  if (!voice) return null;
  const u = new SpeechSynthesisUtterance(text);
  u.voice = voice;
  u.lang = voice.lang;
  u.rate = 0.9;
  const done = new Promise<void>((resolve) => {
    u.onend = () => resolve();
    u.onerror = () => resolve();
  });
  window.speechSynthesis.cancel();
  window.speechSynthesis.speak(u);
  return { source: "device_voice", done, stop: () => window.speechSynthesis.cancel() };
}

async function fetchClip(ref: string): Promise<Blob | null> {
  if (memoryCache.has(ref)) return memoryCache.get(ref)!;
  const saved = await getAudio(ref).catch(() => undefined);
  if (saved) return saved;
  if (!navigator.onLine) return null;
  try {
    const res = await api<Response>(`/speech/clip?ref=${encodeURIComponent(ref)}`, { raw: true });
    const blob = await res.blob();
    memoryCache.set(ref, blob);
    return blob;
  } catch {
    return null;
  }
}

export interface SpeakItem {
  /** Clip ref for pre-generated lesson audio (e.g. "q:<id>:prompt"). Omit for free text. */
  ref?: string;
  text: string;
}

async function serverTts(text: string): Promise<Blob | null> {
  if (!navigator.onLine) return null;
  try {
    const res = await api<Response>("/speech/tts", { method: "POST", body: { text }, raw: true });
    return await res.blob();
  } catch {
    return null;
  }
}

/**
 * Speak a sequence of items (e.g. feedback, then the next question).
 * `sourceReady` resolves once the first item starts, so the UI can say which voice is used.
 */
export function speak(items: SpeakItem[], opts: { textOnly?: boolean } = {}): PlayHandle & {
  sourceReady: Promise<VoiceSource>;
} {
  stopSpeaking();
  if (opts.textOnly || items.length === 0) {
    return { source: "none", done: Promise.resolve(), stop: () => {}, sourceReady: Promise.resolve("none") };
  }
  let stopped = false;
  let active: PlayHandle | null = null;
  let resolveSource: (s: VoiceSource) => void = () => {};
  const sourceReady = new Promise<VoiceSource>((r) => (resolveSource = r));
  const done = (async () => {
    let first = true;
    for (const item of items) {
      if (stopped) break;
      let blob: Blob | null = null;
      let src: VoiceSource = "server_clip";
      if (item.ref) {
        const saved = await getAudio(item.ref).catch(() => undefined);
        if (saved) {
          blob = saved;
          src = "saved_clip";
        } else blob = await fetchClip(item.ref);
      } else {
        blob = await serverTts(item.text);
      }
      if (stopped) break;
      active = blob ? playBlob(blob, src) : speakWithDevice(item.text);
      if (first) {
        resolveSource(active?.source ?? "none");
        first = false;
      }
      if (active) await active.done;
    }
    resolveSource("none");
  })();
  const handle = {
    source: "none" as VoiceSource,
    done,
    stop: () => {
      stopped = true;
      active?.stop();
      resolveSource("none");
    },
    sourceReady,
  };
  void sourceReady.then((src) => (handle.source = src));
  current = handle;
  return handle;
}

/** Speak arbitrary text (e.g. the teacher summary) via server TTS, else device voice. */
export async function speakText(text: string): Promise<PlayHandle> {
  stopSpeaking();
  if (navigator.onLine) {
    try {
      const res = await api<Response>("/speech/tts", { method: "POST", body: { text }, raw: true });
      const h = playBlob(await res.blob(), "server_clip");
      current = h;
      return h;
    } catch {
      /* fall through to device voice */
    }
  }
  const h = speakWithDevice(text) ?? { source: "none" as const, done: Promise.resolve(), stop: () => {} };
  current = h;
  return h;
}
